// Archivio botanico curato. I mesi delle operazioni sono riferiti a pianura e collina
// del Centro-Nord Italia (zona USDA 8); l'app li adatta al clima locale del giardino.
// Ogni voce è specifica per la specie. L'archivio si amplia senza limiti con GBIF, AI e
// inserimento manuale (le specie aggiunte vengono salvate in IndexedDB).
//
// Campi: m = mesi, ty = tipo attività, x = istruzione, p = priorità 1-3,
// sh = attività legata alla temperatura (si sposta con il clima locale).
// Problemi: n nome, k tipo, s sintomi, c cause, pv prevenzione, bio intervento a basso
// impatto, cla intervento convenzionale, r mesi di rischio, d diagnosi differenziale, thr soglia.

const T = (m, ty, x, p = 1, sh = 0) => ({ m, ty, x, p, sh });
const P = (n, k, s, c, pv, bio, cla, r, d, thr) => ({ n, k, s, c, pv, bio, cla, r, d, thr });

